  'use strict';

  const form = document.getElementById('contactForm');
  const successBanner = document.getElementById('successBanner');

  const fields = {
    fullName: {
      el: document.getElementById('fullName'),
      validate(v) {
        if (!v.trim()) return 'Full name is required.';
        if (v.trim().length < 2) return 'Please enter your full name.';
        return null;
      },
    },
    email: {
      el: document.getElementById('email'),
      validate(v) {
        if (!v.trim()) return 'Email address is required.';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())) return 'Please enter a valid email address.';
        return null;
      },
    },
    phone: {
      el: document.getElementById('phone'),
      validate(v) {
        if (!v.trim()) return null; // optional
        if (!/^[+\d][\d\s\-().]{6,19}$/.test(v.trim())) return 'Please enter a valid phone number.';
        return null;
      },
    },
  };

  function getOrCreateMsg(fieldEl) {
    let msg = fieldEl.parentElement.querySelector('.validation-msg');
    if (!msg) {
      msg = document.createElement('span');
      msg.className = 'validation-msg';
      msg.setAttribute('aria-live', 'polite');
      // Insert before helper-text if present, otherwise append
      const helper = fieldEl.parentElement.querySelector('.helper-text');
      helper
        ? fieldEl.parentElement.insertBefore(msg, helper)
        : fieldEl.parentElement.appendChild(msg);
    }
    return msg;
  }

  function validateField(key) {
    const { el, validate } = fields[key];
    const error = validate(el.value);
    const wrapper = el.parentElement;
    const msg = getOrCreateMsg(el);

    if (error) {
      wrapper.classList.add('is-invalid');
      msg.textContent = error;
      el.setAttribute('aria-invalid', 'true');
    } else {
      wrapper.classList.remove('is-invalid');
      msg.textContent = '';
      el.removeAttribute('aria-invalid');
    }
    return !error;
  }

  // Validate on blur — not on initial render
  Object.keys(fields).forEach((key) => {
    const { el } = fields[key];

    el.addEventListener('blur', () => validateField(key));

    // Re-validate on input only if already marked invalid (live feedback)
    el.addEventListener('input', () => {
      if (el.parentElement.classList.contains('is-invalid')) {
        validateField(key);
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    // Validate all fields on submit
    const valid = Object.keys(fields).map(validateField).every(Boolean);
    if (!valid) {
      // Focus the first invalid field
      const firstInvalid = form.querySelector('.is-invalid input');
      if (firstInvalid) firstInvalid.focus();
      return;
    }

    // Simulate submission
    const btn = form.querySelector('.btn-submit');
    btn.disabled = true;
    btn.textContent = 'Sending…';

    setTimeout(() => {
      form.reset();
      Object.keys(fields).forEach((key) => {
        fields[key].el.parentElement.classList.remove('is-invalid');
      });
      btn.disabled = false;
      btn.textContent = 'Send Message';
      successBanner.hidden = false;
      successBanner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 900);
  });
})();
