+/* ── Reset & base ──────────────────────────────────────────── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --bg:            #0f1117;
+  --surface:       #1a1d27;
+  --surface-hover: #22263a;
+  --border:        #2e3249;
+  --border-focus:  #6c63ff;
+  --border-error:  #f05252;
+  --text-primary:  #e8eaf0;
+  --text-muted:    #8b90a7;
+  --accent:        #6c63ff;
+  --accent-hover:  #574fd6;
+  --success:       #22c55e;
+  --error:         #f05252;
+  --radius:        10px;
+  --transition:    0.18s ease;
+}
+
+body {
+  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
+  background: var(--bg);
+  color: var(--text-primary);
+  min-height: 100vh;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  padding: 2rem 1rem;
+}
+
+/* ── Card ──────────────────────────────────────────────────── */
+.page { width: 100%; display: flex; justify-content: center; }
+
+.card {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: 16px;
+  padding: 2.5rem 2rem;
+  width: 100%;
+  max-width: 480px;
+  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.45);
+}
+
+.card__title {
+  font-size: 1.6rem;
+  font-weight: 700;
+  letter-spacing: -0.02em;
+  color: var(--text-primary);
+  margin-bottom: 0.4rem;
+}
+
+.card__subtitle {
+  font-size: 0.9rem;
+  color: var(--text-muted);
+  margin-bottom: 2rem;
+  line-height: 1.5;
+}
+
+/* ── Form fields ───────────────────────────────────────────── */
+form { display: flex; flex-direction: column; gap: 1.25rem; }
+
+.form-field { display: flex; flex-direction: column; gap: 0.4rem; }
+
+.form-field label {
+  font-size: 0.85rem;
+  font-weight: 600;
+  color: var(--text-primary);
+  letter-spacing: 0.01em;
+}
+
+.required { color: var(--accent); }
+
+.form-field input {
+  background: var(--bg);
+  border: 1.5px solid var(--border);
+  border-radius: var(--radius);
+  color: var(--text-primary);
+  font-size: 0.95rem;
+  padding: 0.65rem 0.9rem;
+  outline: none;
+  transition: border-color var(--transition), box-shadow var(--transition);
+  width: 100%;
+}
+
+.form-field input::placeholder { color: var(--text-muted); opacity: 1; }
+
+.form-field input:hover:not(:disabled) { border-color: #4a4f6e; }
+
+.form-field input:focus {
+  border-color: var(--border-focus);
+  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.18);
+}
+
+/* Invalid state — only shown after the user has interacted (via JS class) */
+.form-field.is-invalid input {
+  border-color: var(--border-error);
+  box-shadow: 0 0 0 3px rgba(240, 82, 82, 0.15);
+}
+
+.validation-msg {
+  font-size: 0.78rem;
+  color: var(--error);
+  display: none;
+}
+
+.form-field.is-invalid .validation-msg { display: block; }
+
+/* Helper text */
+.helper-text {
+  font-size: 0.78rem;
+  color: var(--text-muted);
+  line-height: 1.4;
+}
+
+/* ── Submit button ─────────────────────────────────────────── */
+.btn-submit {
+  margin-top: 0.5rem;
+  background: var(--accent);
+  color: #fff;
+  border: none;
+  border-radius: var(--radius);
+  font-size: 0.95rem;
+  font-weight: 600;
+  padding: 0.75rem 1.25rem;
+  cursor: pointer;
+  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
+  letter-spacing: 0.01em;
+}
+
+.btn-submit:hover {
+  background: var(--accent-hover);
+  box-shadow: 0 4px 18px rgba(108, 99, 255, 0.35);
+}
+
+.btn-submit:active { transform: translateY(1px); }
+
+.btn-submit:disabled {
+  opacity: 0.55;
+  cursor: not-allowed;
+  transform: none;
+  box-shadow: none;
+}
+
+/* ── Success banner ────────────────────────────────────────── */
+.success-banner {
+  display: flex;
+  align-items: center;
+  gap: 0.6rem;
+  margin-top: 1.25rem;
+  background: rgba(34, 197, 94, 0.1);
+  border: 1px solid rgba(34, 197, 94, 0.35);
+  border-radius: var(--radius);
+  padding: 0.75rem 1rem;
+  color: var(--success);
+  font-size: 0.9rem;
+  font-weight: 500;
+}
+
+.success-banner svg { width: 18px; height: 18px; flex-shrink: 0; }
+
